import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "at::Tensor ln_forward(at::Tensor x, at::Tensor weight, at::Tensor bias, double eps);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <algorithm>
#include <cstdint>
template <typename T, int BLOCK>
__device__ inline void warp_reduce_pair(T &sum, T &sq) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sq  += __shfl_down_sync(0xffffffff, sq, offset);
    }
}
template <typename T, int BLOCK>
__device__ inline void block_reduce_pair(T &sum, T &sq, T *red_sum, T *red_sq) {
    constexpr int NWARPS = BLOCK / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int wid = tid >> 5;
    warp_reduce_pair<T, BLOCK>(sum, sq);
    if (lane == 0) {
        red_sum[wid] = sum;
        red_sq[wid] = sq;
    }
    __syncthreads();
    if (wid == 0) {
        T s = (lane < NWARPS) ? red_sum[lane] : (T)0;
        T q = (lane < NWARPS) ? red_sq[lane] : (T)0;
        warp_reduce_pair<T, BLOCK>(s, q);
        if (lane == 0) {
            red_sum[0] = s;
            red_sq[0] = q;
        }
    }
    __syncthreads();
    if (tid == 0) {
        sum = red_sum[0];
        sq = red_sq[0];
    }
    __syncthreads();
}
template <typename T, int BLOCK>
__global__ void ln_stats_kernel(
    const T *__restrict__ x,
    T *__restrict__ acc,
    int64_t N,
    int64_t chunks_per_row,
    int64_t total_chunks,
    int chunk_elems,
    int vec_ok) {
    __shared__ T red_sum[BLOCK / 32];
    __shared__ T red_sq[BLOCK / 32];
    const int tid = threadIdx.x;
    for (int64_t chunk = blockIdx.x; chunk < total_chunks; chunk += gridDim.x) {
        int64_t row = chunk / chunks_per_row;
        int64_t cin = chunk - row * chunks_per_row;
        int64_t within = cin * (int64_t)chunk_elems;
        int64_t off = row * N + within;
        int64_t rem = N - within;
        int len = rem < (int64_t)chunk_elems ? (int)rem : chunk_elems;
        T lsum = (T)0;
        T lsq = (T)0;
        if (vec_ok) {
            const float4 *x4 = reinterpret_cast<const float4 *>(x + off);
            int n4 = len >> 2;
            for (int i = tid; i < n4; i += BLOCK) {
                float4 v = x4[i];
                lsum += (T)v.x + (T)v.y + (T)v.z + (T)v.w;
                lsq += (T)v.x * (T)v.x + (T)v.y * (T)v.y + (T)v.z * (T)v.z + (T)v.w * (T)v.w;
            }
            for (int i = (n4 << 2) + tid; i < len; i += BLOCK) {
                T v = x[off + i];
                lsum += v;
                lsq += v * v;
            }
        } else {
            for (int i = tid; i < len; i += BLOCK) {
                T v = x[off + i];
                lsum += v;
                lsq += v * v;
            }
        }
        block_reduce_pair<T, BLOCK>(lsum, lsq, red_sum, red_sq);
        if (tid == 0) {
            atomicAdd(&acc[row * 2 + 0], lsum);
            atomicAdd(&acc[row * 2 + 1], lsq);
        }
        __syncthreads();
    }
}
template <typename T, int BLOCK>
__global__ void ln_normalize_kernel(
    const T *__restrict__ x,
    const T *__restrict__ w,
    const T *__restrict__ b,
    T *__restrict__ y,
    const T *__restrict__ acc,
    int64_t N,
    int64_t chunks_per_row,
    int64_t total_chunks,
    int chunk_elems,
    T eps,
    int vec_ok) {
    __shared__ T s_mean;
    __shared__ T s_rstd;
    const int tid = threadIdx.x;
    for (int64_t chunk = blockIdx.x; chunk < total_chunks; chunk += gridDim.x) {
        int64_t row = chunk / chunks_per_row;
        int64_t cin = chunk - row * chunks_per_row;
        int64_t within = cin * (int64_t)chunk_elems;
        int64_t off = row * N + within;
        int64_t rem = N - within;
        int len = rem < (int64_t)chunk_elems ? (int)rem : chunk_elems;
        if (tid == 0) {
            T s = acc[row * 2 + 0];
            T q = acc[row * 2 + 1];
            T mean = s / (T)N;
            T var = q / (T)N - mean * mean;
            if (var < (T)0) var = (T)0;
            s_mean = mean;
            s_rstd = rsqrt(var + eps);
        }
        __syncthreads();
        T mean = s_mean;
        T rstd = s_rstd;
        if (vec_ok) {
            const float4 *x4 = reinterpret_cast<const float4 *>(x + off);
            const float4 *w4 = reinterpret_cast<const float4 *>(w + within);
            const float4 *b4 = reinterpret_cast<const float4 *>(b + within);
            float4 *y4 = reinterpret_cast<float4 *>(y + off);
            int n4 = len >> 2;
            for (int i = tid; i < n4; i += BLOCK) {
                float4 xv = x4[i];
                float4 wv = w4[i];
                float4 bv = b4[i];
                float4 yv;
                yv.x = ((T)xv.x - mean) * rstd * (T)wv.x + (T)bv.x;
                yv.y = ((T)xv.y - mean) * rstd * (T)wv.y + (T)bv.y;
                yv.z = ((T)xv.z - mean) * rstd * (T)wv.z + (T)bv.z;
                yv.w = ((T)xv.w - mean) * rstd * (T)wv.w + (T)bv.w;
                y4[i] = yv;
            }
            for (int i = (n4 << 2) + tid; i < len; i += BLOCK) {
                T xv = x[off + i];
                y[off + i] = (xv - mean) * rstd * w[within + i] + b[within + i];
            }
        } else {
            for (int i = tid; i < len; i += BLOCK) {
                T xv = x[off + i];
                y[off + i] = (xv - mean) * rstd * w[within + i] + b[within + i];
            }
        }
        __syncthreads();
    }
}
template <typename T>
at::Tensor ln_forward_t(at::Tensor x, at::Tensor weight, at::Tensor bias, double eps) {
    constexpr int BLOCK = 256;
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    auto bc = bias.contiguous();
    auto y = at::empty_like(xc);
    const int64_t N = wc.numel();
    const int64_t total = xc.numel();
    TORCH_CHECK(N > 0);
    TORCH_CHECK(total % N == 0);
    const int64_t outer = total / N;
    auto stream = at::cuda::getCurrentCUDAStream();
    auto acc = at::empty({outer * 2}, xc.options());
    cudaMemsetAsync(acc.data_ptr<T>(), 0, sizeof(T) * (size_t)outer * 2, stream.stream());
    const int vec_ok = ((N & 3) == 0) ? 1 : 0;
    const int chunk_elems = vec_ok ? BLOCK * 4 : BLOCK;
    const int64_t chunks_per_row = (N + chunk_elems - 1) / chunk_elems;
    const int64_t total_chunks = outer * chunks_per_row;
    int dev = 0;
    cudaGetDevice(&dev);
    int sm_count = 0;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, dev);
    if (sm_count < 1) sm_count = 1;
    int64_t want_blocks = (int64_t)sm_count * 8;
    int num_blocks = (int)std::min<int64_t>(want_blocks, total_chunks);
    if (num_blocks < 1) num_blocks = 1;
    ln_stats_kernel<T, BLOCK><<<num_blocks, BLOCK, 0, stream.stream()>>>(
        xc.data_ptr<T>(),
        acc.data_ptr<T>(),
        N,
        chunks_per_row,
        total_chunks,
        chunk_elems,
        vec_ok);
    ln_normalize_kernel<T, BLOCK><<<num_blocks, BLOCK, 0, stream.stream()>>>(
        xc.data_ptr<T>(),
        wc.data_ptr<T>(),
        bc.data_ptr<T>(),
        y.data_ptr<T>(),
        acc.data_ptr<T>(),
        N,
        chunks_per_row,
        total_chunks,
        chunk_elems,
        (T)eps,
        vec_ok);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess);
    return y;
}
at::Tensor ln_forward(at::Tensor x, at::Tensor weight, at::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda());
    TORCH_CHECK(x.scalar_type() == weight.scalar_type() && x.scalar_type() == bias.scalar_type());
    if (x.scalar_type() == at::kFloat) {
        return ln_forward_t<float>(x, weight, bias, eps);
    }
    if (x.scalar_type() == at::kDouble) {
        return ln_forward_t<double>(x, weight, bias, eps);
    }
    TORCH_CHECK(false);
}
"""

_C = load_inline(
    name="custom_layernorm_persistent",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["ln_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.ln = nn.Module()
        self.ln.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.ln.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _C.ln_forward(x, self.ln.weight, self.ln.bias, self.eps)

