template <typename T, int BLOCK>
__device__ inline void block_reduce_pair(T &sum, T &sq, T *red_sum, T *red_sq) {
    constexpr int NWARPS = BLOCK / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int wid = tid >> 5;

    warp_reduce_pair<T, BLOCK>(sum, sq);
    if (lane == 0) {
        red_sum[wid] = sum;
        red_sq[wid] = sq;
    }
    __syncthreads();

    if (wid == 0) {
