__device__ inline void persistent_grid_barrier(int *bar, int num_blocks) {
    __syncthreads();
    if (threadIdx.x == 0) {
        __threadfence();
        int old = atomicAdd(&bar[0], 1);
        if (old == num_blocks - 1) {
            __threadfence();
            atomicExch(&bar[1], 1);
        } else {
            while (atomicAdd(&bar[1], 0) == 0) {
            }
        }
    }
    __syncthreads();
    __threadfence();
