template <typename T, int BLOCK>
__global__ void ln_persistent_kernel(
    const T *__restrict__ x,
    const T *__restrict__ w,
    const T *__restrict__ b,
    T *__restrict__ y,
    T *__restrict__ acc,
    int *__restrict__ bar,
    int64_t outer,
    int64_t N,
    int64_t chunks_per_row,
    int64_t total_chunks,
    int chunk_elems,
    T eps,
    int vec_ok) {
