    const int chunk_elems = vec_ok ? BLOCK * 4 : BLOCK;
    const int64_t chunks_per_row = (N + chunk_elems - 1) / chunk_elems;
    const int64_t total_chunks = outer * chunks_per_row;

    int dev = 0;
    cudaGetDevice(&dev);
    int sm_count = 0;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, dev);

    int max_blocks_per_sm = 0;
    size_t shmem = (size_t)(BLOCK / 32) * sizeof(T);
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &max_blocks_per_sm, ln_persistent_kernel<T, BLOCK>, BLOCK, shmem);
    if (max_blocks_per_sm < 1) max_blocks_per_sm = 1;
    if (max_blocks_per_sm > 4) max_blocks_per_sm = 4;

    int64_t want_blocks = (int64_t)sm_count * max_blocks_per_sm;
    int num_blocks = (int)std::min<int64_t>(want_blocks, total_chunks);
    if (num_blocks < 1) num_blocks = 1;

    ln_persistent_kernel<T, BLOCK><<<num_blocks, BLOCK, shmem, stream.stream()>>>(
        xc.data_ptr<T>(),
        wc.data_ptr<T>(),
        bc.data_ptr<T>(),
        y.data_ptr<T>(),
        acc.data_ptr<T>(),
        bar.data_ptr<int>(),
        outer,
        N,
        chunks_per_row,
        total_chunks,
        chunk_elems,
        (T)eps,
        vec_ok);

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));
    return y;
}

